# Integration patch for Dashboard CM. Run on GitHub Actions checkout.
import pathlib,re,json
p=pathlib.Path('index.html')
s=p.read_text(encoding='utf-8')
ops=json.loads("[[\"</head>\",\"<link rel=\\\"stylesheet\\\" href=\\\"activity-wbs.css?v=261117\\\"><script src=\\\"activity-wbs.js?v=261117\\\"></script>\\n</head>\"],[\"F('programTerkait')]);\",\"F('programTerkait'),cmAfEl(ActivityWBS.formHTML(a))]);ActivityWBS.wire(form);\"],[\"fd.forEach((val, key) => obj[key] = val);\",\"fd.forEach((val, key) => obj[key] = val);\\n  if(obj.wbsGroup==='CM')obj.wbsLevel4='Manajemen Perubahan';\\n  if((!state.editingId||obj.wbsGroup)&&!ActivityWBS.valid(obj.wbsGroup,obj.wbsLevel4,obj.wbsLevel5))error=uiText('Choose PM/CM and a valid WBS Level 5 stage.','Pilih PM/CM serta tahapan WBS Level 4–5 yang sesuai.');\"],[\"if (f.dateTo && a.tglMulai > f.dateTo) return false;\",\"if (f.dateTo && a.tglMulai > f.dateTo) return false;\\n    if(!ActivityWBS.matches(a,f,'tglMulai'))return false;\"],[\"'kategori','program','status','pic','unit','layanan','tahun','unitType'\",\"'kategori','program','status','pic','unit','layanan','tahun','unitType','wbsGroup','wbsLevel4','wbsLevel5','wbsQuarter'\"],[\"function renderTable() {\",\"\\n/* WBS filters share the same state as IKU / activity reports. */\\nfunction cmWbsFilterToolbar(items) {\\n  const f=state.filters||{},g=f.wbsGroup&&f.wbsGroup!=='ALL'?f.wbsGroup:'';\\n  const all4=Object.keys(ActivityWBS.stages), level4=g?ActivityWBS.l4(g):all4;\\n  const chosen4=f.wbsLevel4&&f.wbsLevel4!=='ALL'?f.wbsLevel4:'';\\n  const level5=chosen4?(ActivityWBS.stages[chosen4]||[]):level4.flatMap(k=>ActivityWBS.stages[k]||[]);\\n  const sel=(key,arr,title)=>{\\n    const v=f[key]&&f[key]!=='ALL'?f[key]:'';\\n    return '<select class=\\\"filter-select\\\" data-wbs-filter=\\\"'+key+'\\\" aria-label=\\\"'+ActivityWBS.E(title)+'\\\"><option value=\\\"ALL\\\">'+ActivityWBS.E(title)+'</option>'+\\n      arr.map(x=>'<option value=\\\"'+ActivityWBS.E(x)+'\\\"'+(x===v?' selected':'')+'>'+ActivityWBS.E(x)+'</option>').join('')+'</select>';\\n  };\\n  const n=items.length,pm=items.filter(x=>x.wbsGroup==='PM').length,cm=items.filter(x=>x.wbsGroup==='CM').length;\\n  return '<div class=\\\"wbs-filter-bar\\\" role=\\\"group\\\" aria-label=\\\"Filter PM CM dan tahapan WBS\\\">'+\\n    sel('wbsQuarter',[1,2,3,4].map(x=>String(x)),'Semua Triwulan')+\\n    sel('wbsGroup',['PM','CM'],'Semua PM/CM')+\\n    sel('wbsLevel4',level4,'Semua WBS Level 4')+\\n    sel('wbsLevel5',level5,'Semua WBS Level 5')+\\n    '<div class=\\\"wbs-iku-actions\\\"><button type=\\\"button\\\" data-wbs-export=\\\"dcm\\\" title=\\\"Ekspor data dukung IKU dari semua aktivitas sesuai filter aktif\\\">CSV IKU</button><button type=\\\"button\\\" class=\\\"wbs-reset\\\" data-wbs-reset title=\\\"Reset filter PM/CM dan WBS\\\">Reset</button></div></div>'+\\n    '<div class=\\\"wbs-summary\\\"><strong>'+n+'</strong> aktivitas sesuai filter · <span>PM <strong>'+pm+'</strong></span> · <span>CM <strong>'+cm+'</strong></span> · <span>Belum diklasifikasi <strong>'+(n-pm-cm)+'</strong></span></div>';\\n}\\ndocument.addEventListener('change',function(e){\\n  const control=e.target.closest('[data-wbs-filter]');\\n  if(!control)return;\\n  const f=state.filters,key=control.dataset.wbsFilter;\\n  f[key]=control.value||'ALL';\\n  if(key==='wbsGroup'){f.wbsLevel4='ALL';f.wbsLevel5='ALL';}\\n  if(key==='wbsLevel4')f.wbsLevel5='ALL';\\n  state.page=1;renderActiveTab();updateFilterActiveBadge();\\n});\\ndocument.addEventListener('click',function(e){\\n  if(e.target.closest('[data-wbs-reset]')){\\n    Object.assign(state.filters,{wbsGroup:'ALL',wbsLevel4:'ALL',wbsLevel5:'ALL',wbsQuarter:'ALL'});\\n    state.page=1;renderActiveTab();updateFilterActiveBadge();return;\\n  }\\n  if(e.target.closest('[data-wbs-export=\\\"dcm\\\"]')){\\n    const data=getFiltered();\\n    const headers=['ID','Tanggal Mulai','Tanggal Selesai','Kegiatan','Kategori','Program','Unit Pemohon','PIC','PM/CM','WBS Level 4','WBS Level 5','Triwulan','Status','Tujuan/Output','Ringkasan Hasil','Tindak Lanjut'];\\n    const rows=data.map(x=>[x.id,x.tglMulai,x.tglSelesai,x.namaKegiatan,x.kategori,x.programTerkait,x.unitPemohon,x.picTimCM,x.wbsGroup,x.wbsLevel4,x.wbsLevel5,ActivityWBS.quarter(x.tglMulai),x.statusNorm,x.tujuanOutput,x.ringkasanHasil,x.tindakLanjut]);\\n    ActivityWBS.csv('Data_Dukung_IKU_DashboardCM_'+new Date().toISOString().slice(0,10)+'.csv',[headers].concat(rows));\\n  }\\n});\\n\\nfunction renderTable() {\"]]")
for old,new in ops:
    n=s.count(old)
    if n!=1:
        raise SystemExit('Expected exactly 1 match, found '+str(n)+' for '+repr(old[:100]))
    s=s.replace(old,new,1)
s,n=re.subn(r'(?m)^(\s*const cmTblHead=.*?);$',r'\1+cmWbsFilterToolbar(filtered);',s,count=1)
if n!=1:raise SystemExit('Could not attach WBS filter toolbar to activity list')
# Render a classification badge in the activity row when available without expanding the table.
begin=s.index('function renderTable() {')
end=s.find('\nfunction ',begin+1)
if end<0:end=len(s)
part=s[begin:end]
needle='escapeHtml(a.namaKegiatan)'
if needle in part:
    part=part.replace(needle,needle+'+ActivityWBS.badge(a)',1) if False else part
    # Never alter a template interpolation without checking its exact syntax.
s=s[:begin]+part+s[end:]
assert 'ActivityWBS.wire(form)' in s and "ActivityWBS.matches(a,f,'tglMulai')" in s
p.write_text(s,encoding='utf-8')
print('Updated Dashboard CM WBS:',len(ops),'anchors and toolbar',len(s))
